import{_ as s,o as a,c as l,ah as e}from"./chunks/framework.CPHJ30oF.js";const c=JSON.parse('{"title":"07-Docker数据卷管理实战-持久化再也不怕","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"为什么需要数据卷","slug":"为什么需要数据卷","link":"#为什么需要数据卷","children":[]},{"level":2,"title":"Docker 卷与绑定挂载的区别","slug":"docker-卷与绑定挂载的区别","link":"#docker-卷与绑定挂载的区别","children":[{"level":3,"title":"命名卷（Volume）","slug":"命名卷-volume","link":"#命名卷-volume","children":[]},{"level":3,"title":"绑定挂载（Bind Mount）","slug":"绑定挂载-bind-mount","link":"#绑定挂载-bind-mount","children":[]},{"level":3,"title":"tmpfs 挂载","slug":"tmpfs-挂载","link":"#tmpfs-挂载","children":[]}]},{"level":2,"title":"实战案例：MySQL 持久化","slug":"实战案例-mysql-持久化","link":"#实战案例-mysql-持久化","children":[]},{"level":2,"title":"Docker Compose 中的数据卷","slug":"docker-compose-中的数据卷","link":"#docker-compose-中的数据卷","children":[]},{"level":2,"title":"哪些数据该持久化？","slug":"哪些数据该持久化","link":"#哪些数据该持久化","children":[]},{"level":2,"title":"常见误区","slug":"常见误区","link":"#常见误区","children":[]},{"level":2,"title":"工程化建议","slug":"工程化建议","link":"#工程化建议","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/07-Docker数据卷管理实战-持久化再也不怕.md","filePath":"docker/07-Docker数据卷管理实战-持久化再也不怕.md"}'),h={name:"docker/07-Docker数据卷管理实战-持久化再也不怕.md"};function n(t,i,k,p,r,d){return a(),l("div",null,[...i[0]||(i[0]=[e(`<h1 id="_07-docker数据卷管理实战-持久化再也不怕" tabindex="-1">07-Docker数据卷管理实战-持久化再也不怕 <a class="header-anchor" href="#_07-docker数据卷管理实战-持久化再也不怕" aria-label="Permalink to “07-Docker数据卷管理实战-持久化再也不怕”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>容器生命周期短暂，容器被删除或重建时，内部数据默认会丢失。这对数据库、日志、上传文件、配置等持久化内容来说，是一个必须面对的问题。</p><p>本篇文章讲清楚 Docker 数据卷的使用场景、卷与绑定挂载的区别、实战命令与工程化建议，帮助你从“容器+数据”变成“容器可替换，数据不丢失”。</p><h2 id="为什么需要数据卷" tabindex="-1">为什么需要数据卷 <a class="header-anchor" href="#为什么需要数据卷" aria-label="Permalink to “为什么需要数据卷”">​</a></h2><p>容器是可丢弃的运行单元。如果你把数据库文件、上传内容、日志文件直接写在容器内，容器重建后这些数据会消失。</p><p>例如：</p><ul><li>MySQL 数据库容器重建后，数据目录被清空；</li><li>应用日志默认写入容器内，无法方便地由宿主机或日志系统统一收集；</li><li>上传文件、生成文件等状态数据伴随容器消失。</li></ul><p>数据卷的出现，正是为了解耦“容器生命周期”和“数据生命周期”。</p><h2 id="docker-卷与绑定挂载的区别" tabindex="-1">Docker 卷与绑定挂载的区别 <a class="header-anchor" href="#docker-卷与绑定挂载的区别" aria-label="Permalink to “Docker 卷与绑定挂载的区别”">​</a></h2><h3 id="命名卷-volume" tabindex="-1">命名卷（Volume） <a class="header-anchor" href="#命名卷-volume" aria-label="Permalink to “命名卷（Volume）”">​</a></h3><ul><li>由 Docker 管理；</li><li>与容器生命周期分离；</li><li>更适合生产环境的数据持久化；</li><li>可以在多个容器之间共享。</li></ul><p>示例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydata</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydata:/var/lib/mysql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql:8</span></span></code></pre></div><h3 id="绑定挂载-bind-mount" tabindex="-1">绑定挂载（Bind Mount） <a class="header-anchor" href="#绑定挂载-bind-mount" aria-label="Permalink to “绑定挂载（Bind Mount）”">​</a></h3><ul><li>直接把宿主机目录挂载到容器；</li><li>适合本地开发和调试；</li><li>依赖宿主机目录结构和权限；</li><li>不适合生产环境中作为主要持久化方案。</li></ul><p>示例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">roject</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ata:/app/data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp:latest</span></span></code></pre></div><h3 id="tmpfs-挂载" tabindex="-1">tmpfs 挂载 <a class="header-anchor" href="#tmpfs-挂载" aria-label="Permalink to “tmpfs 挂载”">​</a></h3><ul><li>数据保存在内存中；</li><li>容器重启后丢失；</li><li>适合缓存、临时文件和敏感数据。</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tmpfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp:rw,size=100m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp:latest</span></span></code></pre></div><h2 id="实战案例-mysql-持久化" tabindex="-1">实战案例：MySQL 持久化 <a class="header-anchor" href="#实战案例-mysql-持久化" aria-label="Permalink to “实战案例：MySQL 持久化”">​</a></h2><p>使用命名卷：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql-data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MYSQL_ROOT_PASSWORD=secret</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql-data:/var/lib/mysql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql:8</span></span></code></pre></div><p>如果你删除容器：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span></span></code></pre></div><p>数据仍然会保留在 <code>mysql-data</code> 卷中，再次启动容器即可恢复。</p><h2 id="docker-compose-中的数据卷" tabindex="-1">Docker Compose 中的数据卷 <a class="header-anchor" href="#docker-compose-中的数据卷" aria-label="Permalink to “Docker Compose 中的数据卷”">​</a></h2><p>Compose 文件中定义卷更加清晰：</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3.9&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  db</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql:8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      MYSQL_ROOT_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql-data:/var/lib/mysql</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mysql-data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>使用 <code>docker-compose up -d</code> 启动后，数据卷会自动创建并挂载。</p><h2 id="哪些数据该持久化" tabindex="-1">哪些数据该持久化？ <a class="header-anchor" href="#哪些数据该持久化" aria-label="Permalink to “哪些数据该持久化？”">​</a></h2><p>通常应持久化：</p><ul><li>数据库文件；</li><li>用户上传内容；</li><li>业务日志；</li><li>配置文件；</li><li>重要缓存或状态。</li></ul><p>通常不该持久化：</p><ul><li>临时构建产物；</li><li>应用运行时缓存；</li><li>临时 session 文件；</li><li>可重建的缓存内容。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>误以为绑定挂载就是“持久化最佳实践”。本地开发时方便，但生产环境下容易带来权限和一致性问题。</li><li>误把容器内路径当成数据目录。容器重建后该路径会丢失。</li><li>误把所有数据都写入同一个卷。不同数据类型最好拆分卷，便于备份和迁移。</li></ul><h2 id="工程化建议" tabindex="-1">工程化建议 <a class="header-anchor" href="#工程化建议" aria-label="Permalink to “工程化建议”">​</a></h2><ul><li>生产环境优先使用命名卷；</li><li>重要数据定期备份卷内容；</li><li>绑定挂载仅用于开发环境；</li><li>业务数据与临时数据分开；</li><li>使用 Compose 或编排工具统一管理卷定义。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>Docker 数据卷让你把“容器可丢弃，数据必须保留”的思想落地。理解命名卷与绑定挂载的差异，并根据场景选择最合适的方案，才能让容器化应用既灵活又稳健。</p>`,42)])])}const g=s(h,[["render",n]]);export{c as __pageData,g as default};
